<template>
  <div class="updates-page">
    <h1>{{ t('nodes.updates.title') }}</h1>

    <el-card class="version-card">
      <template #header>
        <div class="card-header">
          <span>{{ t('nodes.updates.publishedVersions') }}</span>
          <el-button type="primary" @click="showPublishDialog = true">
            {{ t('nodes.updates.publishNew') }}
          </el-button>
        </div>
      </template>

      <el-table :data="versions" v-loading="versionsLoading" style="width: 100%">
        <el-table-column prop="version" :label="t('nodes.updates.version')" width="120" />
        <el-table-column prop="channel" :label="t('nodes.updates.channel')" width="100" />
        <el-table-column prop="filename" :label="t('nodes.updates.filename')" />
        <el-table-column prop="checksum" label="SHA256" show-overflow-tooltip />
        <el-table-column prop="is_mandatory" :label="t('nodes.updates.mandatory')" width="100">
          <template #default="{ row }">
            <el-tag v-if="row.is_mandatory" type="danger">{{ t('common.yes') }}</el-tag>
            <el-tag v-else type="info">{{ t('common.no') }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column prop="created_at" :label="t('nodes.updates.publishedAt')" width="180">
          <template #default="{ row }">
            {{ formatDate(row.created_at) }}
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <el-card class="nodes-card">
      <template #header>
        <span>{{ t('nodes.updates.nodeUpdateStatus') }}</span>
      </template>

      <el-table :data="nodes" v-loading="nodesLoading" style="width: 100%">
        <el-table-column prop="name" :label="t('nodes.nodeName')" />
        <el-table-column prop="node_id" :label="t('nodes.nodeId')" />
        <el-table-column prop="platform" :label="t('nodes.platform')" width="100" />
        <el-table-column prop="status" :label="t('common.status')" width="100">
          <template #default="{ row }">
            <el-tag :type="statusType(row.status)">{{ row.status }}</el-tag>
          </template>
        </el-table-column>
        <el-table-column :label="t('common.actions')" width="150">
          <template #default="{ row }">
            <el-button size="small" type="primary" @click="handleUpdate(row)">
              {{ t('nodes.updates.triggerUpdate') }}
            </el-button>
          </template>
        </el-table-column>
      </el-table>
    </el-card>

    <el-dialog v-model="showPublishDialog" :title="t('nodes.updates.publishDialogTitle')" width="600px">
      <el-form :model="publishForm" label-width="120px" :rules="publishRules" ref="publishFormRef">
        <el-form-item :label="t('nodes.updates.version')" prop="version">
          <el-input v-model="publishForm.version" :placeholder="t('nodes.updates.versionPlaceholder')" />
        </el-form-item>
        <el-form-item :label="t('nodes.updates.channel')" prop="channel">
          <el-select v-model="publishForm.channel" :placeholder="t('nodes.updates.channelPlaceholder')">
            <el-option label="stable" value="stable" />
            <el-option label="beta" value="beta" />
          </el-select>
        </el-form-item>
        <el-form-item :label="t('nodes.updates.filename')" prop="filename">
          <el-input v-model="publishForm.filename" :placeholder="t('nodes.updates.filenamePlaceholder')" />
        </el-form-item>
        <el-form-item label="SHA256" prop="checksum">
          <el-input v-model="publishForm.checksum" :placeholder="t('nodes.updates.checksumPlaceholder')" />
        </el-form-item>
        <el-form-item :label="t('nodes.updates.mandatory')">
          <el-switch v-model="publishForm.is_mandatory" />
        </el-form-item>
        <el-form-item :label="t('nodes.updates.releaseNotes')">
          <el-input v-model="publishForm.release_notes" type="textarea" :rows="3" />
        </el-form-item>
      </el-form>
      <template #footer>
        <el-button @click="showPublishDialog = false">{{ t('common.cancel') }}</el-button>
        <el-button type="primary" @click="submitPublish" :loading="publishing">
          {{ t('nodes.updates.publish') }}
        </el-button>
      </template>
    </el-dialog>
  </div>
</template>

<script setup lang="ts">
import { ElMessage, ElMessageBox } from 'element-plus'
import { onMounted, reactive, ref } from 'vue'
import { useI18n } from 'vue-i18n'
import type { FormInstance, FormRules } from 'element-plus'
import { getNodes, type NodeRead } from '@/api/nodes'
import {
  listAgentVersions,
  publishAgentVersion,
  triggerNodeUpdate,
  type AgentVersion,
  type AgentVersionCreate,
} from '@/api/agentVersion'

const { t } = useI18n()

const versions = ref<AgentVersion[]>([])
const nodes = ref<NodeRead[]>([])
const versionsLoading = ref(false)
const nodesLoading = ref(false)
const showPublishDialog = ref(false)
const publishing = ref(false)
const publishFormRef = ref<FormInstance>()

const publishForm = reactive<AgentVersionCreate>({
  version: '',
  channel: 'stable',
  filename: '',
  checksum: '',
  is_mandatory: false,
  release_notes: '',
})

const publishRules: FormRules = {
  version: [
    { required: true, message: () => t('nodes.updates.versionRequired'), trigger: 'blur' },
    { pattern: /^\d+\.\d+\.\d+$/, message: () => t('nodes.updates.versionFormat'), trigger: 'blur' },
  ],
  filename: [{ required: true, message: () => t('nodes.updates.filenameRequired'), trigger: 'blur' }],
  checksum: [
    { required: true, message: () => t('nodes.updates.checksumRequired'), trigger: 'blur' },
    { pattern: /^[0-9a-fA-F]{64}$/, message: () => t('nodes.updates.checksumFormat'), trigger: 'blur' },
  ],
}

function formatDate(value: string | null | undefined): string {
  if (!value) return '-'
  return new Date(value).toLocaleString()
}

function statusType(status: string): string {
  switch (status) {
    case 'online':
      return 'success'
    case 'offline':
      return 'danger'
    default:
      return 'info'
  }
}

async function loadVersions() {
  versionsLoading.value = true
  try {
    versions.value = await listAgentVersions()
  } finally {
    versionsLoading.value = false
  }
}

async function loadNodes() {
  nodesLoading.value = true
  try {
    const result = await getNodes()
    nodes.value = result.items
  } finally {
    nodesLoading.value = false
  }
}

async function submitPublish() {
  const valid = await publishFormRef.value?.validate().catch(() => false)
  if (!valid) return

  publishing.value = true
  try {
    await publishAgentVersion({ ...publishForm })
    ElMessage.success(t('nodes.updates.publishSuccess'))
    showPublishDialog.value = false
    publishFormRef.value?.resetFields()
    await loadVersions()
  } finally {
    publishing.value = false
  }
}

async function handleUpdate(row: NodeRead) {
  try {
    await ElMessageBox.confirm(
      t('nodes.updates.confirmUpdate', { name: row.name }),
      t('nodes.updates.confirmUpdateTitle'),
      { confirmButtonText: t('common.ok'), cancelButtonText: t('common.cancel'), type: 'warning' },
    )
    const task = await triggerNodeUpdate(row.id)
    ElMessage.success(t('nodes.updates.updateTaskCreated', { taskId: task.task_id }))
  } catch (error) {
    if (error !== 'cancel') {
      ElMessage.error(error instanceof Error ? error.message : t('nodes.updates.triggerUpdateFailed'))
    }
  }
}

onMounted(() => {
  loadVersions()
  loadNodes()
})
</script>

<style scoped>
.updates-page {
  padding: 20px;
}

.version-card,
.nodes-card {
  margin-bottom: 20px;
}

.card-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
</style>
