import apiClient from './client'

export interface AgentVersion {
  id: number
  version: string
  channel: string
  filename: string
  checksum: string
  is_mandatory: boolean
  release_notes?: string | null
  created_at: string
}

export interface AgentVersionCreate {
  version: string
  channel?: string
  filename: string
  checksum: string
  is_mandatory?: boolean
  release_notes?: string
}

export interface AgentUpdateTask {
  task_id: string
  node_id: string
  target_version: string
  status: string
  created_at: string
}

export async function listAgentVersions(channel?: string): Promise<AgentVersion[]> {
  const response = await apiClient.get<AgentVersion[]>('/v1/admin/agent-versions', {
    params: channel ? { channel } : undefined,
  })
  return response.data
}

export async function publishAgentVersion(data: AgentVersionCreate): Promise<AgentVersion> {
  const response = await apiClient.post<AgentVersion>('/v1/admin/agent-versions', data)
  return response.data
}

export async function triggerNodeUpdate(nodeId: number): Promise<AgentUpdateTask> {
  const response = await apiClient.post<AgentUpdateTask>(`/v1/nodes/${nodeId}/update`)
  return response.data
}
